import{_ as p,a0 as u,w as a,s,I as l,x as n,a1 as r,A as o,ao as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"如何在Ubuntu/CentOS上安装Linux内核4.0 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Ubuntu/CentOS上安装Linux内核4.0 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Ubuntu/CentOS上安装Linux内核4.0 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Ubuntu/CentOS上安装Linux内核4.0 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150417 How to Install Linux Kernel 4.0 from Elrepo or Source on Ubuntu or CentOs","title":"如何在Ubuntu/CentOS上安装Linux内核4.0","tag":"201504","desc":""},"relativePath":"201504/20150417 How to Install Linux Kernel 4.0 from Elrepo or Source on Ubuntu or CentOs.md","filePath":"[post].md"}'),d={name:"201504/20150417 How to Install Linux Kernel 4.0 from Elrepo or Source on Ubuntu or CentOs.md"};function x(m,e,g,b,h,L){const t=u("Link");return a(),s("div",null,[e[22]||(e[22]=l("h1",{id:"如何在ubuntu-centos上安装linux内核4-0",tabindex:"-1"},[n("如何在Ubuntu/CentOS上安装Linux内核4.0 "),l("a",{class:"header-anchor",href:"#如何在ubuntu-centos上安装linux内核4-0","aria-label":"Permalink to “如何在Ubuntu/CentOS上安装Linux内核4.0”"},"​")],-1)),l("p",null,[e[1]||(e[1]=n("大家好，今天我们学习一下如何从Elrepo或者源代码来安装最新的Linux内核4.0。代号为‘Hurr durr I'm a sheep’的Linux内核4.0是目前为止最新的主干内核。它是稳定版3.19.4之后发布的内核。4月12日是所有的开源运动爱好者的大日子，Linux Torvalds宣布了Linux内核4.0的发布，它现在就已经可用了。由于包括了一些很棒的功能，例如无重启补丁(实时补丁)，新的升级驱动，最新的硬件支持以及很多有趣的功能都有新的版本，它原本被期望是一次重要版本。但是实际上内核4.0并不认为是期望中的重要版本，Linus 表示期望4.1会是一个更重要的版本。实时补丁功能已经集成到了SUSE企业版Linux操作系统上。你可以在",-1)),r(t,{href:"http://linux.cn/article-5259-1.html"},{default:o(()=>[...e[0]||(e[0]=[n("发布公告",-1)])]),_:1}),e[2]||(e[2]=n("上查看关于这次发布的更多详细内容。",-1))]),e[23]||(e[23]=i(`<blockquote><p><strong>警告</strong>： 安装新的内核可能会导致你的系统不可用或不稳定。如果你仍然使用以下命令继续安装，请确保备份所有重要数据到外部硬盘。</p></blockquote><h3 id="在ubuntu-15-04上安装linux内核4-0" tabindex="-1">在Ubuntu 15.04上安装Linux内核4.0 <a class="header-anchor" href="#在ubuntu-15-04上安装linux内核4-0" aria-label="Permalink to “在Ubuntu 15.04上安装Linux内核4.0”">​</a></h3><p>如果你正在使用Linux的发行版Ubuntu 15.04，你可以直接通过Ubuntu内核网站安装。在你的Ubuntu15.04上安装最新的Linux内核4.0，你需要在shell或终端中在root访问权限下运行以下命令。</p><h4 id="在-64位-ubuntu-15-04" tabindex="-1">在 64位 Ubuntu 15.04 <a class="header-anchor" href="#在-64位-ubuntu-15-04" aria-label="Permalink to “在 64位 Ubuntu 15.04”">​</a></h4><pre><code>$ wget http://kernel.ubuntu.com/~kernel-ppa/mainline/v4.0-vivid/linux-image-4.0.0-040000-generic_4.0.0-040000.201504121935_amd64.deb
$ wget http://kernel.ubuntu.com/~kernel-ppa/mainline/v4.0-vivid/linux-headers-4.0.0-040000-generic_4.0.0-040000.201504121935_amd64.deb

$ sudo dpkg -i linux-headers-4.0.0*.deb linux-image-4.0.0*.deb
</code></pre><h4 id="在-32位-ubuntu-15-04" tabindex="-1">在 32位 Ubuntu 15.04 <a class="header-anchor" href="#在-32位-ubuntu-15-04" aria-label="Permalink to “在 32位 Ubuntu 15.04”">​</a></h4><pre><code>$ wget http://kernel.ubuntu.com/~kernel-ppa/mainline/v4.0-vivid/linux-image-4.0.0-040000-generic_4.0.0-040000.201504121935_i386.deb
$ wget http://kernel.ubuntu.com/~kernel-ppa/mainline/v4.0-vivid/linux-headers-4.0.0-040000-generic_4.0.0-040000.201504121935_i386.deb

$ sudo dpkg -i linux-headers-4.0.0*.deb linux-image-4.0.0*.deb
</code></pre><h3 id="在centos-7上安装linux内核4-0" tabindex="-1">在CentOS 7上安装Linux内核4.0 <a class="header-anchor" href="#在centos-7上安装linux内核4-0" aria-label="Permalink to “在CentOS 7上安装Linux内核4.0”">​</a></h3><p>我们可以用两种简单的方式在CentOS 7上安装Linux内核4.0。</p><ol><li>从Elrepo软件仓库安装</li><li>从源代码编译安装</li></ol><p>我们首先用ElRepo安装，这是最简单的方式：</p><h4 id="使用-elrepo-安装" tabindex="-1">使用 Elrepo 安装 <a class="header-anchor" href="#使用-elrepo-安装" aria-label="Permalink to “使用 Elrepo 安装”">​</a></h4><p><strong>1. 下载和安装ELRepo</strong></p><p>我们首先下载ELRepo的GPG密钥并安装relrepo-release安装包。因为我们用的是CentOS 7，我们使用以下命令安装elrepo-release-7.0-2.el7.elrepo.noarch.rpm。</p>`,14)),l("p",null,[e[4]||(e[4]=n("注: 如果你启用了secure boot，请查看",-1)),r(t,{href:"http://elrepo.org/tiki/SecureBootKey"},{default:o(()=>[...e[3]||(e[3]=[n("这个网页获取更多信息",-1)])]),_:1}),e[5]||(e[5]=n("。",-1))]),e[24]||(e[24]=i(`<pre><code># rpm --import https://www.elrepo.org/RPM-GPG-KEY-elrepo.org
# rpm -Uvh http://www.elrepo.org/elrepo-release-7.0-2.el7.elrepo.noarch.rpm
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/adding-elrepo.png" alt="添加 Elrepo 源"></p><p><strong>2. 升级Linux内核到4.0版本</strong></p><p>现在，我们准备从ELRepo软件仓库安装最新的稳定版内核4.0。安装它我们需要在CentOS 7的shell或者终端中输入以下命令。</p><pre><code># yum --enablerepo=elrepo-kernel install kernel-ml
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/installing-kernel-4-0-elrepo.png" alt="从ELRepo安装Linux内核4.0"></p><p>上面的命令会自动安装为CentOS 7构建的Linux内核4.0。</p><p>现在，下面的是另一种方式，通过编译源代码安装最新的内核4.0。</p><h4 id="从源代码编译安装" tabindex="-1">从源代码编译安装 <a class="header-anchor" href="#从源代码编译安装" aria-label="Permalink to “从源代码编译安装”">​</a></h4><p><strong>1. 安装依赖软件</strong></p><p>首先我们需要为编译linux内核安装依赖的软件。要完成这些，我们需要在一个终端或者shell中运行以下命令。</p><pre><code># yum groupinstall &quot;Development Tools&quot;

# yum install gcc ncurses ncurses-devel
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/installing-dependencies.png" alt="安装内核依赖"></p><p>然后，我们会升级我们的整个系统。</p><pre><code># yum update
</code></pre><p><strong>2. 下载源代码</strong></p>`,16)),l("p",null,[e[7]||(e[7]=n("现在我们通过wget命令从Linux内核的官方仓库中下载最新发布的linux内核4.0的源代码。你也可以使用你的浏览器直接从",-1)),r(t,{href:"http://kernel.org/"},{default:o(()=>[...e[6]||(e[6]=[n("kernel.org",-1)])]),_:1}),e[8]||(e[8]=n("网站下载内核。",-1))]),e[25]||(e[25]=i(`<pre><code>#  cd /tmp/
# wget https://www.kernel.org/pub/linux/kernel/v4.x/linux-4.0.tar.xz
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/download-kernel-source.png" alt="下载内核源码"></p><p><strong>3. 解压tar压缩包</strong></p><p>文件下载好后我们在/usr/src/文件夹下用以下命令解压。</p><pre><code># tar -xf linux-4.0.tar.xz -C /usr/src/
# cd /usr/src/linux-4.0/
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/extracting-kernel-tarball.png" alt="解压内核tar压缩包"></p><p><strong>4. 配置</strong></p><p>配置Linux内核有两种选择的。我们可以创建一个新的自定义配置文件或者使用已有的配置文件来构建和安装Linux内核。这都取决于你自己的需要。</p><p><strong>配置新的内核</strong></p><p>现在我们在shell或终端中运行make menuconfig命令来配置Linux内核。我们执行以下命令后会显示一个包含所有菜单的弹出窗口。在这里我们可以选择我们新的内核配置。如果你不熟悉这些菜单，那就敲击ESC键两次退出。</p><pre><code># make menuconfig
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/configuring-new-kernel-config.png" alt="配置新内核"></p><p><strong>已有的配置</strong></p><p>如果你想用已有的配置文件配置你最新的内核，那就输入下面的命令。如果你对配置有任何调整，你可以选择Y或者N，或者仅仅是按Enter键继续。</p><pre><code># make oldconfig
</code></pre><h4 id="step-5-编译linux内核" tabindex="-1">Step 5. 编译Linux内核 <a class="header-anchor" href="#step-5-编译linux内核" aria-label="Permalink to “Step 5. 编译Linux内核”">​</a></h4><p>下一步，我们会执行make命令来编译内核4.0。取决于你的系统配置，编译至少需要20-30分钟。</p><p>注：如果编译内核的时候出现<code>bc command not found</code>的错误，你可以用<strong>yum install bc</strong>命令安装bc修复这个错误。</p><pre><code># make
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/make-kernel.png" alt="Make 内核"></p><h4 id="_6-安装linux内核4-0" tabindex="-1">6. 安装Linux内核4.0 <a class="header-anchor" href="#_6-安装linux内核4-0" aria-label="Permalink to “6. 安装Linux内核4.0”">​</a></h4><p>编译完成后，我们终于要在你的Linux系统上安装<strong>内核</strong>了。下面的命令会在/boot目录下创建文件并且在Grub 菜单中新建一个内核条目。</p><pre><code># make modules_install install
</code></pre><h4 id="_7-验证内核" tabindex="-1">7. 验证内核 <a class="header-anchor" href="#_7-验证内核" aria-label="Permalink to “7. 验证内核”">​</a></h4><p>安装完最新的内核4.0后我们希望能验证它。做这些我们只需要在终端中输入以下命令。如果所有都进展顺利，我们会看到内核版本，例如4.0出现在输出列表中。</p><pre><code># uname -r
</code></pre><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h4><p>好了，我们成功地在我们的CentOS 7操作系统上安装了最新的Linux内核版本4.0。通常并不需要升级linux内核，因为和之前版本运行良好的硬件可能并不适合新的版本。我们要确保它包括能使你的硬件正常工作的功能和配件。但大部分情况下，新的稳定版本内核能使你的硬件性能更好。因此，如果你有任何问题，评论，反馈，请在下面的评论框中注明，让我们知道需要增加或者删除什么问题。多谢！享受最新的稳定版Linux内核4.0吧 😃</p><hr>`,29)),l("p",null,[e[10]||(e[10]=n("via: ",-1)),r(t,{href:"http://linoxide.com/how-tos/install-linux-kernel-4-0-elrepo-source/"},{default:o(()=>[...e[9]||(e[9]=[n("http://linoxide.com/how-tos/install-linux-kernel-4-0-elrepo-source/",-1)])]),_:1})]),l("p",null,[e[14]||(e[14]=n("作者：",-1)),r(t,{href:"http://linoxide.com/author/arunp/"},{default:o(()=>[...e[11]||(e[11]=[n("Arun Pyasi",-1)])]),_:1}),e[15]||(e[15]=n(" 译者：",-1)),r(t,{href:"https://github.com/ictlyh"},{default:o(()=>[...e[12]||(e[12]=[n("ictlyh",-1)])]),_:1}),e[16]||(e[16]=n(" 校对：",-1)),r(t,{href:"https://github.com/wxy"},{default:o(()=>[...e[13]||(e[13]=[n("wxy",-1)])]),_:1})]),l("p",null,[e[19]||(e[19]=n("本文由 ",-1)),r(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[17]||(e[17]=[n("LCTT",-1)])]),_:1}),e[20]||(e[20]=n(" 原创翻译，",-1)),r(t,{href:"http://linux.cn/"},{default:o(()=>[...e[18]||(e[18]=[n("Linux中国",-1)])]),_:1}),e[21]||(e[21]=n(" 荣誉推出",-1))])])}const C=p(d,[["render",x]]);export{k as __pageData,C as default};
